t.script:
//
document.addEventListener('DOMContentLoaded', function() {
    const CATEGORIES = [
        { id:'industrial', name:'Industrial' },
        { id:'marine',     name:'Marine' },
        { id:'fabric',     name:'Fabric' },
        { id:'climbing',   name:'Climbing' },
    ];
    const PRODUCTS = [
        { id:'p1', name:'Industrial Manila Rope', cat:'industrial', price:24.90, unit:'/ 10m', rating:4.8, badge:'Bestseller', ropeClass:'rt-manila', tags:['12mm','Natural fibre','High grip'] },
        { id:'p2', name:'Polypropylene Utility Rope', cat:'industrial', price:14.50, unit:'/ 15m', rating:4.6, badge:'', ropeClass:'rt-poly', tags:['10mm','Waterproof','Lightweight'] },
        { id:'p3', name:'Steel-Core Hoist Rope', cat:'industrial', price:58.00, unit:'/ 10m', rating:4.9, badge:'Pro', ropeClass:'rt-steel', tags:['16mm','Steel core','2.5T WLL'] },
        { id:'p4', name:'Marine Double-Braid Rope', cat:'marine', price:39.90, unit:'/ 10m', rating:4.9, badge:'New', ropeClass:'rt-marine', tags:['12mm','UV stable','Low stretch'] },
        { id:'p5', name:'Anchor Nylon Rope', cat:'marine', price:32.00, unit:'/ 20m', rating:4.7, badge:'', ropeClass:'rt-nylon', tags:['14mm','Shock absorbing','Saltproof'] },
        { id:'p6', name:'Floating Dock Line', cat:'marine', price:21.50, unit:'/ 10m', rating:4.5, badge:'', ropeClass:'rt-float', tags:['10mm','Floats','Hi-vis'] },
        { id:'p7', name:'Soft Cotton Braided Rope', cat:'fabric', price:12.90, unit:'/ 10m', rating:4.8, badge:'Bestseller', ropeClass:'rt-cotton', tags:['8mm','100% cotton','Soft touch'] },
        { id:'p8', name:'Macramé Cord Bundle', cat:'fabric', price:9.50, unit:'/ 25m', rating:4.9, badge:'Top rated', ropeClass:'rt-macrame', tags:['4mm','Crafts','Natural'] },
        { id:'p9', name:'Coloured Fabric Rope', cat:'fabric', price:15.90, unit:'/ 10m', rating:4.6, badge:'', ropeClass:'rt-color', tags:['6mm','12 colours','Washable'] },
        { id:'p10', name:'Dynamic Climbing Rope', cat:'climbing', price:129.00, unit:'/ 50m', rating:5.0, badge:'Certified', ropeClass:'rt-dynamic', tags:['9.8mm','UIAA','Dynamic'] },
        { id:'p11', name:'Static Rigging Rope', cat:'climbing', price:89.00, unit:'/ 50m', rating:4.8, badge:'', ropeClass:'rt-static', tags:['11mm','Static','Rescue'] },
        { id:'p12', name:'Accessory Cord', cat:'climbing', price:11.00, unit:'/ 10m', rating:4.7, badge:'', ropeClass:'rt-cord', tags:['6mm','Multi-use','Strong'] },
    ];
    function catName(id){ return (CATEGORIES.find(c=>c.id===id)||{}).name||id; }
    const PROD_IMGS = {
        p1: '/theme_cordage/static/src/images/img3.jpg',
        p2: '/theme_cordage/static/src/images/img6.webp',
        p3: '/theme_cordage/static/src/images/img1.jpg',
        p4: '/theme_cordage/static/src/images/img4.jpg',
        p5: '/theme_cordage/static/src/images/img5.webp',
        p6: '/theme_cordage/static/src/images/img2.jpg',
        p7: '/theme_cordage/static/src/images/img7.webp',
        p8: '/theme_cordage/static/src/images/img8.webp',
        p9: '/theme_cordage/static/src/images/img9.webp',
        p10: '/theme_cordage/static/src/images/img1.jpg',
        p11: '/theme_cordage/static/src/images/img4.jpg',
        p12: '/theme_cordage/static/src/images/img7.webp',
    };

    let activeCat = 'all';
    const ROW_LIMIT = 8;
    const grid = document.getElementById('productGrid');
    const empty = document.getElementById('emptyState');
    const btn = document.getElementById('showMoreBtn');

    function renderDemoProducts() {
        if (!grid) return;
        const list = PRODUCTS.filter(p => activeCat === 'all' || p.cat === activeCat);
        if (empty) empty.hidden = list.length > 0;

        grid.innerHTML = list.slice(0, ROW_LIMIT).map((p, i) => `
            <article class="bni-pcard${i >= ROW_LIMIT ? ' pcard-extra' : ''}">
                <a href="/cordage-product?id=${p.id}" style="display:block;text-decoration:none">
                    <div class="bni-pcard__media ${p.ropeClass || ''}">
                        <img class="bni-pcard__photo" src="${PROD_IMGS[p.id] || ''}" alt="${p.name}" loading="lazy" onerror="this.style.display='none'"/>
                        ${p.badge ? '<span class="bni-pcard__badge">' + p.badge + '</span>' : ''}
                    </div>
                </a>
                <div class="bni-pcard__body">
                    <div class="bni-pcard__cat">${catName(p.cat)}</div>
                    <a href="/cordage-product?id=${p.id}" class="bni-pcard__name">${p.name}</a>
                    <div class="bni-pcard__specs">
                        ${(p.tags || []).map(t => '<span class="bni-pcard__spec-pill">' + t + '</span>').join('')}
                    </div>
                    <div class="bni-pcard__rating">
                        <span>${'★'.repeat(Math.round(p.rating))}</span> ${p.rating.toFixed(1)}
                    </div>
                    <div class="bni-pcard__foot">
                        <span class="bni-pcard__price">$${p.price.toFixed(2)}<span class="bni-pcard__unit">${p.unit}</span></span>
                        <a href="/shop" class="bni-pcard__add cordage-add-cart">Add to Cart</a>
                    </div>
                </div>
            </article>`).join('');

        if (btn) {
            btn.style.display = list.length > ROW_LIMIT ? 'inline-block' : 'none';
        }
    }

    renderDemoProducts();
});
//
